-- FSQM-015 Environmental Monitoring Program. Seeded DRAFT with three open items.
--
-- DELIVERABLE. D-16 task 16.5 ("Write the environmental monitoring program"), Wave 1. It also
-- frames 16.7 (the presumptive-positive response), which is Part 7 here rather than a separate
-- document -- splitting one programme across three documents so that each task owns a file is how
-- a reader ends up with three partial accounts of one control.
--
-- WHAT IT CLOSES, AND WHAT IT DOES NOT. 2.4.8.1 requires the programme to be documented AND
-- implemented. This closes the documented limb only, and says so in the governing reference rather
-- than implying a running programme. The implemented limb needs a laboratory, a sample plan and a
-- results log, none of which exist. That is the FSQM-017 2.5.1.1 pattern and the FSQM-014 "the site
-- does not analyse" pattern: state the gap, because the first thing an auditor does is ask to see
-- the results.
--
-- IT NAMES NO RESULTS-LOG FORM NUMBER, DELIBERATELY. FSQM-022 Rev 1 referenced a "Form-0010 Food
-- Safety Inspection" that was never built, and that dangling reference WAS the finding scored
-- against it (D-13 task 13.4). A form reference is written when the form exists.
--
-- THE SAMPLE PLAN IS NOT IN HERE. 2.4.8.2 wants points, counts, frequency and rotation. Points are
-- placed against the hygiene zones on FSQM-039, whose boundaries have been drawn but not confirmed
-- on the floor -- FSQM-039 is in draft for exactly that reason. Placing points against unconfirmed
-- boundaries means placing them twice. The plan is task 16.6.
--
-- ONE CONSEQUENTIAL AMENDMENT IS RECORDED, NOT PERFORMED. FSQM-014 Part 2 says no external
-- laboratory is used. Read in context that is about product and stays true, but the first
-- environmental sample makes the site a laboratory user and a reader of FSQM-014 alone would be
-- misled. It is scoped to product analysis by the issue migration, in the same transaction that
-- activates this -- not afterwards, and not silently.
--
-- SEEDED DRAFT. No effective_date and no approved_by: both are set by the issue migration, the
-- pattern FSQM-036, FSQM-020, FSQM-039 and FRM-507/606 all follow.

begin;

do $$
declare n int;
begin
  select count(*) into n from public.sop_documents where sop_number = 'FSQM-015';
  if n <> 0 then
    raise exception 'FSQM-015 already exists.';
  end if;

  -- Part 2 and the governing reference both lean on FSQM-014's product-analysis position. If it
  -- is not active, this programme's central distinction has nothing behind it.
  select count(*) into n from public.sop_documents
   where sop_number = 'FSQM-014' and status = 'active';
  if n <> 1 then
    raise exception 'FSQM-014 is not active; FSQM-015 Part 2 and Part 6 depend on it.';
  end if;

  -- Part 7 routes every corrective action through the CAPA programme. Without it the response
  -- procedure has nowhere to land, which is the failure 2.4.8.3's 2.5.3.1 referral describes.
  select count(*) into n from public.sop_documents
   where sop_number = 'FSQM-009' and status = 'active';
  if n <> 1 then
    raise exception 'FSQM-009 is not active; FSQM-015 Part 7 routes CAPAs through it.';
  end if;

  -- Part 6 requires the laboratory on the contract services register before the first sample.
  select count(*) into n from public.sop_documents
   where sop_number = 'FRM-206' and status = 'active';
  if n <> 1 then
    raise exception 'FRM-206 is not active; FSQM-015 Part 6 lists the laboratory on it.';
  end if;
end $$;

insert into public.sop_documents
  (sop_number, title, type, category, status, revision, sqf_reference, sqf_required, content)
values (
  'FSQM-015',
  'Environmental Monitoring Program',
  'fsqm',
  'Food Safety Quality Manual',
  'draft',
  'New',
  '2.4.8.1, .2, .3, 11.7.1.2',
  true,
  $j015${"purpose": "This program states how Adventure Bakery monitors its production environment for pathogens and indicator organisms: who is responsible, where and when samples are taken, which organisms are tested for and why, what is done when a result is unsatisfactory, and how results are trended. It exists because product is open to the room after the oven, which is the site's only kill step, and environmental monitoring is the only control that looks for contamination in the room rather than in the product. It addresses the Environmental Monitoring element of the SQF Food Safety Code: Food Manufacturing, Edition 9 (2.4.8), and the ambient air testing required by 11.7.1.2.", "scope": "The production floor of units 415 and 425 in both configurations of the two-day rotation, the packaging materials storage, the ambient warehouse in which finished product is held, and the immediate surrounding areas that impact them.\n\nDELIBERATELY OUT OF SCOPE, and not to be read as omissions:\n\nAnalysis of raw material, packaging, work-in-progress or finished product. FSQM-014 Part 2 records that this site inspects and does not analyse, and this program does not change that. Every sample taken under this program comes from the room.\n\nThe hygiene zoning itself, which is FSQM-039, and the GMP controls applying to the areas it divides, which are FSQM-012.\n\nThe cleaning and sanitation program in the 900 series. This program measures whether that cleaning is working; it does not specify it and does not replace the pre-operational inspection recorded on FRM-903.", "definitions": "Environmental monitoring zone (Zone 1 to Zone 4): a classification of a sample point by its proximity to exposed product. It is a property of the point, not a place on the floor, and it is not the same as the hygiene areas drawn on FSQM-039. See Part 3.\n\nPost-lethality exposure: the period after product leaves the oven during which it is open to the room — cooling on racks, the dip, and loading into the vacuum sealer.\n\nIndicator organism: an organism tested for not because it is itself the hazard, but because finding it shows conditions in which the hazard could survive or grow.\n\nPresumptive positive: a screening result indicating the target organism may be present, reported before confirmatory testing is complete.\n\nVector swabbing: additional samples taken around a positive result to locate the source of the organism rather than the place it was found.\n\nHarbourage: a place in which an organism survives cleaning and establishes a resident population — typically a crack, a hollow frame, a drain or a standing wet area.", "responsibility": "SQF Practitioner — owns this program. Sets and maintains the sample plan, takes or supervises sampling, receives and interprets results, decides the response to an unsatisfactory result, raises the CAPA where one is required, reports the trend, and reviews this program annually.\nSenior Site Management — approves this program, funds the testing at the frequency the sample plan states, and provides the resources any corrective action requires.\nProduction Supervisor — ensures the area is in the state the sample plan requires when samples are taken, and ensures no sample point is specially cleaned because it is about to be swabbed.\nProduction staff — work to the hygiene controls in FSQM-012 and report any condition that could contaminate product while it is open to the room.\nExternal laboratory — performs the analysis by the named method and reports the result. Accredited and registered as Part 6 requires.", "procedure": ["Product is exposed to the room after the kill step, and that exposure is what this program monitors.", "> The oven is this site's kill step. After it, product cools on open racks, is dipped, and is loaded into the vacuum sealer — all of it open to the room. Anything living in that room during that window can reach the product without passing through another lethal step. Nothing downstream of the oven kills; the seal excludes.", "> That is the whole reason this program exists, and it is why the program looks at the room rather than at the product. A pathogen that establishes itself in a drain, a rack or the frame of the sealer reaches a small and shifting fraction of units. Testing finished product for it is a well-documented way to keep finding nothing while the problem continues.", "> SQF 2.4.8.1 asks for a risk-based program covering the manufacturing processes and the immediate surrounding areas that impact them, with the responsibility and the methods documented and implemented. Parts 2 to 8 are that program.", "This program covers the room. It does not test product, and it does not change the position FSQM-014 takes on product analysis.", "• In scope: the production floor of units 415 and 425 on both days of the rotation, and the surfaces, drains, floors, walls, equipment, cleaning tools and air within it; the packaging materials storage; and the ambient warehouse in which finished product is held.", "• In scope: the annual test of ambient air in the high-care area required by 11.7.1.2.", "• Not in scope: any analysis of raw material, packaging, work-in-progress or finished product. FSQM-014 Part 2 records that the site inspects and does not analyse, and nothing here disturbs that. An environmental sample is taken from the room, never from the product.", "• Not in scope: the hygiene zoning itself, which is drawn on FSQM-039, and the GMP controls over the areas it divides, which are FSQM-012.", "• Not in scope: the cleaning and sanitation program in the 900 series. This program measures whether that cleaning is working. It does not specify it, and it is not a substitute for the pre-operational inspection recorded on FRM-903.", "> The distinction between an environmental sample and a product sample is not a technicality and is stated here because the two documents must be read together. FSQM-014 Part 2 says plainly that no external laboratory is used. That sentence is about product, and Part 6 below records the amendment it needs once an environmental sample is first sent.", "Samples are classified by how close the surface is to exposed product, in four zones. This is not the same thing as the hygiene areas drawn on FSQM-039.", "• Zone 1 — surfaces that contact exposed product. Cooling racks and trays, the dunk tank and anything that enters it, utensils, the sealer's product bed, and hands and gloves that handle open product.", "• Zone 2 — non-product-contact surfaces close to Zone 1. Equipment frames, housings, control panels, the outside of the sealer, rack uprights and castors, the underside of tables.", "• Zone 3 — other surfaces within the production area. Floors, drains, walls, door handles, waste bins, pallet jacks, cleaning tools and their storage, hoses and the mop sink.", "• Zone 4 — areas outside the production area. Storage, corridors, welfare and locker areas, the office side, and the routes between them.", "> FSQM-039 divides the floor by hygiene status — NON-PRODUCTION, PACKAGING MATERIALS STORAGE, RAW / PRE-BAKE, BAKE, COOLING and HIGH CARE. Those describe what is allowed to happen in a place. The zones above describe what a positive result found in a place would mean. The two are different questions and they cut across each other, so a sample point is identified by both: 'dunk tank drip tray — Zone 1, HIGH CARE'.", "> Naming them both is deliberate. A programme that carried only the hygiene areas could not say why a swab of a floor matters less than a swab of a rack; one that carried only the zones could not say why the same bay is sampled differently on the two days of the rotation.", "> THE DUNK BAY IS THE POINT WHERE THE TWO OVERLAP AND MATTER MOST. It holds raw batter on Day 1 and post-bake product on Day 2, and what separates those is the changeover clean and nothing else. Its Zone 1 and Zone 2 points are therefore the most informative surfaces in the building, and the sample plan weights them accordingly.", "The target organisms are Listeria species in the post-lethality area and Enterobacteriaceae as a hygiene indicator, and both are provisional until the finished product's water activity is measured.", "• Listeria species — the pathogen target, sampled in the high-care and cooling areas and in the dunk bay on Day 2. Listeria species rather than Listeria monocytogenes alone: the genus is the harbourage indicator, it is the cheaper and more sensitive screen, and a site that waits for the species to appear has waited too long.", "• Enterobacteriaceae — the hygiene indicator, sampled on food-contact and near-contact surfaces after cleaning. It is inexpensive enough to run often, which is what makes a trend possible at all.", "• Ambient air in the high-care area — tested at least annually under 11.7.1.2, with the method and the acceptance criteria named on the sample plan.", "> WHY LISTERIA. The dip is a wet step, it sits inside the high-care area, and it happens after the only kill step in the process. Standing water, a drain and a cooled product surface in one bay is the classic description of where Listeria establishes itself. That combination is present here on Day 2, so the organism is monitored whether or not the finished product turns out to support its growth.", "> WHY NOT SALMONELLA ON THE DRY SIDE. Flour and other dry ingredients are a well-known Salmonella vehicle, and monitoring for it upstream of the oven was considered and rejected. Everything on the raw side passes through the bake, which is the validated kill step, so a positive found there would not implicate product and would not change any control. Spending the testing budget upstream of a kill step buys information the kill step has already answered. If the process ever gains a route by which raw-side material reaches product after the oven — a rework loop, a topping added cold, a shared utensil — this decision is revisited immediately.", "> WHY BOTH TARGETS ARE PROVISIONAL. The HACCP plan calls the product shelf-stable on the grounds of reduced water activity, but that claim is made about the cake as it leaves the oven and the dip comes after it. Dipping in rum, water and sugar syrup adds water back. The figure that actually governs shelf stability is the water activity of the finished, sealed, equilibrated unit, and that figure is not measured and appears nowhere in the document set. Until it does, this program takes the conservative position and monitors as though growth in product were possible. When the measurement exists the target organisms are reviewed against it, and if the finished product cannot support growth the emphasis here properly shifts toward indicator organisms and away from pathogen screening.", "> That measurement is not this program's to make; it belongs to the food safety plan. This Part records the dependency so that the choice made here can be explained rather than merely asserted, which is what 2.4.8.2 (i) asks for when it requires the applicable pathogens or indicator organisms for the industry to be detailed.", "Samples are taken after cleaning and before production, except at points that can only be judged in use.", "> PRE-OPERATIONAL SAMPLING IS A DELIBERATE CHOICE AND IT IS THE PROPORTIONATE ONE HERE. A Zone 1 swab taken during a run places the running batch in question, and there is no laboratory turnaround fast enough to resolve that before the product would otherwise ship. Sampling after the clean and before production means a positive implicates the clean, which is a condition the site can act on, rather than a lot it would have to hold for days waiting on a result.", "> It is not the more lenient choice. A surface that is positive after cleaning is a surface the cleaning did not reach, which is precisely the finding this program is for.", "• Points that can only be meaningfully assessed in use — drains, the floor around the dunk tank, waste handling — are sampled during or immediately after a run, and the sample plan marks them as such.", "• Swabs are taken by the SQF Practitioner, or by a person the SQF Practitioner has trained and recorded as competent on FRM-952.", "• Each sample records the sample point and its zone, the date and time, whether the area was pre-operational or in use, the organism requested, and who took it.", "• Each swab covers the area the laboratory's method specifies, and the same area at the same point each time, so that results from one point can be compared with each other.", "• Samples are held and transported as the laboratory instructs and are sent the same day they are taken.", "• A sample point shall not be given a clean it would not otherwise have received because it is about to be swabbed.", "> The last rule is the one that decides whether any of the others are worth performing. A point that is specially cleaned before sampling reports on a clean that does not happen in the ordinary course, and the programme then measures its own preparation.", "The analysis is performed by an external laboratory, and the method is settled before the laboratory, and the laboratory before the first sample.", "• The laboratory shall be accredited to ISO/IEC 17025, or to an equivalent international standard, for each method it performs for this site.", "• The laboratory shall be listed on FRM-206 Contract Services Register before the first sample is sent to it, with its accreditation held on that entry.", "• The sample plan shall name, for each organism, the method used, its detection limit, the sample type the method requires, and the reporting time.", "> That order — method, then laboratory, then sample — is FSQM-014 Part 2's rule and it is adopted here unchanged. A sample sent before the method is settled produces a number nobody can interpret and a result nobody can defend.", "> A CONSEQUENTIAL AMENDMENT, RECORDED SO THE TWO DOCUMENTS DO NOT DISAGREE. FSQM-014 Part 2 states that no external laboratory is used and that no analysis is commissioned. Read in context that statement is about raw material, packaging, work-in-progress and finished product, and it remains true of all four. But the first environmental sample sent for analysis makes this site a user of an external laboratory, and a reader of FSQM-014 alone would be misled. FSQM-014 Part 2 is therefore amended to scope its sentence to product analysis, in the same revision that brings this program into force — not afterwards.", "An unsatisfactory result is investigated, and the investigation starts before the confirmation comes back.", "• A presumptive positive is treated as a positive for the purpose of starting work. Confirmation is requested, and the investigation begins without waiting for it.", "• Vector swabbing is carried out around the point — the surfaces, drains and equipment it drains to, sits on, touches or shares a route with — to find where the organism is living rather than merely where it was found.", "• The point is cleaned and sanitised, then re-swabbed, and sampling at that point is intensified until three consecutive negative results are obtained.", "• Where the same organism returns to the same point, the response addresses the cause — standing water, a cracked surface, a hollow frame, a cleaning method that cannot reach — and not the surface alone.", "• A CAPA is raised under FSQM-009 wherever its Part 3 requires one. A confirmed Zone 1 positive for Listeria species in the post-lethality area always raises one.", "• Where a Zone 1 positive is found on a surface that contacted exposed product, the product that contacted it is placed on Hold under FSQM-018 and recorded on FRM-702, and release is refused under FSQM-020 until the disposition is made.", "> This Part is written before the first positive rather than after it, and that is the whole of its value. The pressure at the moment a positive arrives is to explain it away — a bad swab, a one-off, a laboratory error — and a site that has not decided in advance what it will do is deciding it under exactly the conditions that produce the wrong answer.", "> A single positive in Zone 3 is information and not an emergency. The same organism at the same point three times is a resident population, and finding resident populations is what this program is for. Neither statement licenses ignoring the first result.", "> 2.4.8.2 (iv) requires the methods for handling elevated or undesirable results to be described, and this Part is that description.", "Results are trended, and the trend is reviewed by management. A file of results is not compliance with 2.4.8.3.", "• Every result is recorded with its sample point, zone, date, organism, method, laboratory and outcome, on the environmental monitoring results log.", "• The SQF Practitioner reviews the results at least monthly and reports them on FRM-009 Monthly SQF Update.", "• The trend over the year is reviewed at the annual management review and recorded on FRM-001.", "• The SQF Practitioner reviews this program at least annually, and before that whenever the floor is re-zoned, the process changes, the finished product's water activity is measured, or the results themselves indicate the plan is looking in the wrong places.", "> What counts as a trend here: repeat positives at one point, a drift upward in indicator counts at any point, a cluster of positives sharing a drain or a route, and — the one most often missed — a listed point that has not actually been sampled.", "> 2.4.8.3 requires results to be monitored, tracked and trended and preventive action to be taken where an unsatisfactory result or trend is seen, referring to 2.5.3.1. That referral is the CAPA program, FSQM-009, which exists and is active, so the preventive-action limb has somewhere to land."], "form_references": "FRM-206 Contract Services Register — where the external laboratory is listed, with its accreditation, before the first sample is sent.\nFRM-007 CAPA Report — where a corrective and preventive action arising from a positive result is raised and closed.\nFRM-702 Non-Conforming Material Hold & Tagging Record — where product implicated by a Zone 1 positive is placed on hold.\nFRM-009 Monthly SQF Update — where the monthly results review is reported.\nFRM-001 Management Review Record — where the annual trend is reviewed.\nFRM-952 Training and Competency Record — where a person trained to take samples is recorded as competent.\n\nTHE RESULTS LOG DOES NOT YET EXIST AND IS DELIBERATELY NOT NAMED HERE. A program that references a form that was never built is the exact finding FSQM-022 Rev 1 carried against it. The log is built, numbered and named in this Part before this program issues; until then this document states the requirement in Part 8 and points at no number.", "records": "Sample records and laboratory reports — every result, held with its sample point, zone, date, organism, method, laboratory and outcome on the environmental monitoring results log once that log exists. Laboratory reports are retained as received.\n\nInvestigation and corrective action records — on FRM-007 under FSQM-009.\n\nProduct hold and disposition records — on FRM-702 under FSQM-018.\n\nMonthly review — on FRM-009. Annual trend review — on FRM-001.\n\nRetention follows the record control requirements of FSQM-008. Superseded revisions of this program are retained by the sop_document_history trigger, which snapshots the row whenever a watched field changes on a published document.", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 — 2.4.8 Environmental Monitoring. 2.4.8.1 requires a risk-based program for all food manufacturing processes and the immediate surrounding areas which impact them, with the responsibility and methods documented and implemented. 2.4.8.2 requires a sampling and testing schedule detailing the applicable pathogens or indicator organisms, the number and frequency of samples, the locations and their rotation, and the methods for handling elevated or undesirable results. 2.4.8.3 requires results to be monitored, tracked and trended with preventive action under 2.5.3.1.\n\n11.7.1.2 requires ambient air in high-risk areas to be tested at least annually to confirm it does not pose a risk to food safety. That test is in this program's scope and is placed on the sample plan.\n\nWHAT THIS DOCUMENT CLOSES, AND WHAT IT DOES NOT. 2.4.8.1 requires the program to be documented AND implemented. This document is the documented limb. The implemented limb requires an accredited laboratory, a sample plan and a results log, none of which exist as this is written — see the open items in the revision history. 2.4.8.2 is framed here and satisfied by the sample plan, which is a separate piece of work because it depends on zone boundaries that are not yet confirmed on the floor. Recording that plainly is the same choice FSQM-017 made in recording that 2.5.1.1 closes only in part, and FSQM-014 made in stating that the site does not analyse.\n\nFSQM-039 Facility Layout and Product Flow — the hygiene zoning this program's sample points are placed against. It is in draft; its zone boundaries are the dependency named above.\nFSQM-012 Good Manufacturing Practices Program — the personnel, premises and processing controls that keep the room in the condition this program samples.\nFSQM-014 Product Sampling, Inspection and Analysis Program — the product-side counterpart to this document, and the source of the method-then-laboratory-then-sample rule adopted in Part 6. Its Part 2 is amended when this program issues; see Part 6.\nFSQM-009 Corrective and Preventive Action (CAPA) Program — where a positive result's corrective and preventive action is raised, which is the 2.5.3.1 referral 2.4.8.3 makes.\nFSQM-018 Non-Conforming Product and Equipment — where product implicated by a Zone 1 positive is held and dispositioned.\nFSQM-020 Product Release Program — the release that is refused while such a hold stands.\nFSQM-017 Validation and Verification Program — the master verification schedule this program's activities join when it issues.", "revision_history": "Rev New — written 2026-09-17. DRAFT. Not approved, not in force.\n\nWHY IT EXISTS. The site had no environmental monitoring program of any kind, and 2.4.8.1 was scored against that absence. The need is not formal: product cools, is dipped and is loaded into the sealer while open to the room, so the room is the last place contamination can enter and the only place it can be looked for before the pack is closed.\n\nWHAT IT DELIBERATELY DOES NOT DO. It does not set the sample plan. The plan places points against zone boundaries that FSQM-039 has drawn but that nobody has yet confirmed by standing in the building, and points placed against unconfirmed boundaries would have to be placed again. It also does not name a results log, because naming a form that does not exist is the precise defect FSQM-022 Rev 1 carried.\n\nOPEN BEFORE ISSUE — THREE ITEMS, ALL OF THEM COST OR JUDGEMENT:\n\n1. THE TARGET ORGANISM SET IS PROPOSED, NOT CONFIRMED. Part 4 proposes Listeria species in the post-lethality area and Enterobacteriaceae as the hygiene indicator, with the reasoning for each and for rejecting Salmonella on the dry side. This decides what the program costs to run, so it is Senior Site Management's to confirm and not the author's to assume.\n\n2. NO LABORATORY IS ENGAGED. One must be selected, confirmed accredited to ISO/IEC 17025 or equivalent for the methods used, and listed on FRM-206 Contract Services Register. Its price per sample is also what makes the sample plan's frequency decidable, so this item gates more than itself. It would be this site's second contracted service; pest control is the first.\n\n3. THE RESULTS LOG DOES NOT EXIST. It is built, numbered and named in Part 8 and in the form references before this program issues.\n\nDECIDED, AND NOT OPEN:\n\nSampling is pre-operational by default — after the clean, before production — except at points that can only be judged in use. Part 5 gives the reasoning: a positive then implicates the clean, which the site can act on, rather than a lot it would hold for days awaiting a result.\n\nListeria is monitored at the genus level rather than waiting for L. monocytogenes.\n\nThe dry side upstream of the oven is not monitored for pathogens, because everything on it passes through the validated kill step. Part 4 states what would reverse that: any route by which raw-side material reaches product after the oven.\n\nSTATED DEPENDENCY, AND NOT A DEFECT:\n\nThe target organisms are provisional until the finished product's water activity is measured on a sealed, equilibrated unit. That measurement belongs to the food safety plan, not to this program. Until it exists this program takes the conservative position and monitors as though growth in product were possible. Part 4 records what changes when the figure arrives.\n\nCONSEQUENTIAL ON ISSUE — ONE ITEM:\n\nFSQM-014 Part 2 states that no external laboratory is used. That is true of product analysis and stays true, but it reads as a statement about the site. It is scoped to product analysis in the same revision that brings this program into force, so that the two documents never disagree in the interval.", "attachments": []}$j015$::jsonb
);

do $$
declare c jsonb;
begin
  select content into c from public.sop_documents where sop_number = 'FSQM-015';

  if jsonb_array_length(c->'procedure') <> 60 then
    raise exception 'FSQM-015 procedure has %, expected 60', jsonb_array_length(c->'procedure');
  end if;

  -- A count, not a presence check. A guard that only asserts "the text I wrote is there" passes
  -- against a half-written body just as happily.
  if (select count(*) from jsonb_array_elements_text(c->'procedure') s
       where s not like '> %' and s not like '•%') <> 8 then
    raise exception 'FSQM-015 should carry 8 Part headings.';
  end if;

  -- The results log must stay unnamed until it exists; see the header.
  if c::text ~ 'FRM-7[0-9][0-9] Environmental' then
    raise exception 'FSQM-015 names a results-log form number that does not exist.';
  end if;

  if c->>'revision_history' not like '%OPEN BEFORE ISSUE - THREE ITEMS%'
 and c->>'revision_history' not like '%OPEN BEFORE ISSUE — THREE ITEMS%' then
    raise exception 'FSQM-015 open-item block missing.';
  end if;
end $$;

commit;

-- AFTER THIS RUNS, THREE THINGS GATE ISSUE, and none of them is SQL:
--   1. Senior Site Management confirms the target organism set in Part 4 (it sets the cost).
--   2. A laboratory is selected, its ISO/IEC 17025 accreditation confirmed, and it is entered on
--      FRM-206 Contract Services Register.
--   3. The environmental monitoring results log is built and named in Part 8 and in the form
--      references.
-- The sample plan (task 16.6) additionally waits on the FSQM-039 zone boundaries being confirmed
-- on the floor. The issue migration activates this document, stamps it, scopes FSQM-014 Part 2 to
-- product analysis, and adds the environmental monitoring rows to verification_schedule.
